/**
 * @method
 * @name bit2me#createOrderWs
 * @description create a trade order over the websocket
 * @see https://api.bit2me.com/docs/pro/websocket-commands
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much you want to trade in units of the base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, required for limit orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint, the same as for createOrder
 * @param {float} [params.triggerPrice] the price at which a stop-limit order is activated, requires a limit price
 * @param {float} [params.cost] for market orders only, the amount to trade in units of the quote currency, overrides amount
 * @param {string} [params.clientOrderId] a unique identifier for the order
 * @returns {object} an [order structure](https://docs.ccxt.com/#/?id=order-structure)
 */
func (this *Bit2me) CreateOrderWsAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan ccxt.AsyncResult[ccxt.Order] {
	ch := make(chan ccxt.AsyncResult[ccxt.Order], 1)
	go this.createOrderWsBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Bit2me) createOrderWsBody(ch chan ccxt.AsyncResult[ccxt.Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var price *float64 = ccxt.GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params

	r := <-this.LoadMarketsAsync()
	if r.Err != nil {
		panic(r.Err)
	}

	r1 := <-this.AuthenticateAsync()
	if r1.Err != nil {
		panic(r1.Err)
	}
	var market map[string]any = this.Market(symbol)
	var restRequest map[string]any = this.CreateOrderRequest(symbol, typeVar, side, amount, price, params)
	var orderType *string = this.SafeString(restRequest, "orderType")
	if orderType != nil && *orderType == "oco" {
		panic(ccxt.NotSupported(this.Id + " createOrderWs() does not support oco orders, use createOrder() instead"))
	}
	// createOrderRequest always sets a CCXT-<id> clientOrderId, the response is matched by it
	var clientOrderId *string = this.SafeString(restRequest, "clientOrderId")
	var request map[string]any = this.OmitDict(restRequest, "orderType")
	request["event"] = "add-order"
	request["type"] = orderType
	request["clientOrderId"] = clientOrderId
	// the response carries no request id, it is matched by the client order id, and an error only by the symbol
	var pending map[string]any
	pending, _ = this.Options["pendingWsOrders"].(map[string]any)
	if pending == nil {
		pending = map[string]any{}
	}
	if clientOrderId != nil {
		pending[*clientOrderId] = market["id"]
	}
	this.Options["pendingWsOrders"] = pending
	var url *string = this.UrlsApiStrings["ws"]
	var messageHash string = "added-order:" + *clientOrderId

	r2 := <-this.Watch(url, messageHash, request, messageHash)
	if r2.Err != nil {
		panic(r2.Err)
	}
	ch <- ccxt.AsyncResult[ccxt.Order]{Value: ccxt.OrderFromMap(r2.Value)}
	return nil
}

/**
 * @ignore
 * @method
 * @name bit2me#settleRequest
 * @description resolves or rejects a one-shot command and forgets its subscription so the same command can be sent again
 * @param {object} client the websocket client
 * @param {string} messageHash the message hash of the command
 * @param {object} result the value to resolve with
 * @param {object} [error] when set the command is rejected with it instead
 */
func (this *Bit2me) SettleRequest(client any, messageHash string, result any, optionalArgs ...any) {
	error := ccxt.GetArg(optionalArgs, 0, nil)
	_ = error
	if client.(ccxt.ClientInterface).SubscriptionHas(messageHash) {
		client.(ccxt.ClientInterface).SubscriptionDel(messageHash)
	}
	if error != nil {
		client.(ccxt.ClientInterface).Reject(error, messageHash)
	} else {
		client.(ccxt.ClientInterface).Resolve(result, messageHash)
	}
}
func (this *Bit2me) HandleCreateOrder(client any, message map[string]any) {
	//
	//     {
	//         "event": "added-order",
	//         "symbol": "BTC/USDC",
	//         "data": {
	//             "id": "f0f895d1-f9e0-494c-87b4-40e12ce344a1",
	//             "userId": "7bd4cc22-7682-4e45-85b3-29386b979d75",
	//             "side": "buy",
	//             "symbol": "BTC/USDC",
	//             "status": "open",
	//             "orderType": "limit",
	//             "createdAt": "2026-11-11T06:27:02.617Z",
	//             "updatedAt": "2026-11-11T06:27:02.617Z",
	//             "clientOrderId": "c4022a5f-cfb3-46ff-9136-2739e34dd4e6",
	//             "cancelReason": null,
	//             "timeInForce": "GTC",
	//             "feeCurrency": null,
	//             "price": 36000,
	//             "orderAmount": 0.0001,
	//             "filledAmount": 0,
	//             "cost": 0,
	//             "stopPrice": 0,
	//             "feeAmount": 0,
	//             "orderGroupId": null
	//         }
	//     }
	//
	var data map[string]any = this.SafeDictMap(message, "data", map[string]any{})
	var order map[string]any = ccxt.OrderToMap(this.ParseOrder(data))
	var clientOrderId *string = this.SafeString(data, "clientOrderId")
	if clientOrderId != nil {
		var pending map[string]any
		pending, _ = this.Options["pendingWsOrders"].(map[string]any)
		if pending == nil {
			pending = map[string]any{}
		}
		this.Options["pendingWsOrders"] = this.Omit(pending, clientOrderId)
		this.SettleRequest(client, "added-order:"+*clientOrderId, order)
	}
}

