/**
 * @ignore
 * @method
 * @name bit2me#authenticate
 * @description authenticates the websocket connection with a short-lived token obtained over REST
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} the authentication message
 */
func (this *Bit2me) AuthenticateAsync(optionalArgs ...any) <-chan ccxt.AsyncResult[*string] {
	ch := make(chan ccxt.AsyncResult[*string], 1)
	go this.authenticateBody(ch, optionalArgs...)
	return ch
}
func (this *Bit2me) authenticateBody(ch chan ccxt.AsyncResult[*string], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var url *string = this.UrlsApiStrings["ws"]
	var client ccxt.ClientInterface = this.Client(url)
	var messageHash string = "authenticated"
	var future *ccxt.Future = client.(ccxt.ClientInterface).ReusableFuture(messageHash)
	var authenticated bool = client.(ccxt.ClientInterface).SubscriptionSafe(messageHash) != nil
	if !authenticated {
		// the token is valid for one minute, it is only used to open the session

		r := <-this.PrivatePostV1SigninApikey(params)
		if r.Err != nil {
			panic(r.Err)
		}
		var response map[string]any = r.Value
		//
		//     { "accessToken": { "token": "header.payload.signature", "expirationTime": 1794378427 } }
		//
		var accessToken, _ = response["accessToken"].(map[string]any)
		var request map[string]any = map[string]any{
			"event": "authenticate",
			"token": this.SafeString(accessToken, "token"),
		}
		this.Watch(url, messageHash, request, messageHash)
	}

	r1 := <-future.Await()
	if r1.Err != nil {
		panic(r1.Err)
	}
	var resolved *string
	switch resolvedBox := r1.Value.(type) {
	case *string:
		resolved = resolvedBox
	case string:
		resolved = &resolvedBox
	default:
		_ = resolvedBox
	}
	ch <- ccxt.AsyncResult[*string]{Value: resolved}
	return nil
}
func (this *Bit2me) HandleAuthenticate(client any, message map[string]any) {
	//
	//     { "event": "authenticate" }
	//     { "event": "authenticate", "error": "jwt expired" }
	//
	var messageHash string = "authenticated"
	var error *string = this.SafeString(message, "error")
	if error == nil {
		// the future is reusable, every later authenticate() call awaits the same resolved value
		var future *ccxt.Future = client.(ccxt.ClientInterface).GetFutures()[messageHash]
		future.Resolve(message)
	} else {
		exception := ccxt.AuthenticationError(this.Id + " " + this.Json(message))
		client.(ccxt.ClientInterface).Reject(exception, messageHash)
		if client.(ccxt.ClientInterface).SubscriptionHas(messageHash) {
			client.(ccxt.ClientInterface).SubscriptionDel(messageHash)
		}
	}
}
func (this *Bit2me) HandleSubscriptionStatus(client any, message map[string]any) map[string]any {
	//
	//     { "event": "subscribe", "symbol": "BTC/USDC", "subscription": { "name": "order-book" }, "result": "subscribed" }
	//     { "event": "unsubscribe" }
	//
	return message
}
func (this *Bit2me) HandleErrorMessage(client any, message map[string]any) {
	//
	//     { "event": "added-order", "symbol": "BTC/USDC", "error": { "code": "PRICE_LOWER_MARKET_MIN", "minPrice": 0.001, "message": "The price can not be lower than 0.001" } }
	//     { "event": "canceled-order", "orderId": "73352609-a885-4dc6-99c4-8a03e5df6bda", "error": { "code": "ORDER_NOT_FOUND", "message": "The order with ID 73352609-a885-4dc6-99c4-8a03e5df6bda was not found" } }
	//
	var event *string = this.SafeString(message, "event")
	var error, _ = message["error"].(map[string]any)
	var code *string = this.SafeString(error, "code")
	var errorMessage *string = this.SafeString(error, "message")
	var feedback string = this.Id + " " + this.Json(message)
	var exception any = nil

	{
		func(this *Bit2me) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Bit2me) any {
						// catch block:
						exception = e
						return nil
					}(this)
				}
			}()
			// try block:
			this.ThrowExactlyMatchedException(this.Exceptions["exact"], code, feedback)
			this.ThrowBroadlyMatchedException(this.Exceptions["broad"], errorMessage, feedback)
			exception = ccxt.ExchangeError(feedback)
			return nil
		}(this)

	}
	if event != nil && *event == "added-order" {
		// the error carries no client order id, reject every order of the symbol still waiting for a response
		var marketId *string = this.SafeString(message, "symbol")
		var pending map[string]any
		pending, _ = this.Options["pendingWsOrders"].(map[string]any)
		if pending == nil {
			pending = map[string]any{}
		}
		var clientOrderIds []string = nil
		if pending != nil {
			clientOrderIds = make([]string, 0, len(pending))
			for objectKey := range pending {
				clientOrderIds = append(clientOrderIds, objectKey)
			}
		}
		for i := 0; i < len(clientOrderIds); i++ {
			var clientOrderId string = clientOrderIds[i]
			if ccxt.IsEqual(pending[clientOrderId], marketId) {
				this.SettleRequest(client, "added-order:"+clientOrderId, nil, exception)
				this.Options["pendingWsOrders"] = this.Omit(this.Options["pendingWsOrders"], clientOrderId)
			}
		}
	} else if event != nil && *event == "canceled-order" {
		this.SettleRequest(client, "canceled-order:"+*this.SafeString(message, "orderId", ""), nil, exception)
	} else if event != nil && *event == "canceled-orders" {
		this.SettleRequest(client, "canceled-orders", nil, exception)
	} else if event != nil && *event == "canceled-all-orders" {
		this.SettleRequest(client, "canceled-all-orders:"+*this.SafeString(message, "symbol", ""), nil, exception)
	} else if event != nil && *event == "subscribe" {
		// a refused subscription names the channel and the symbol it was asked for
		var subscription, _ = message["subscription"].(map[string]any)
		var name *string = this.SafeString(subscription, "name")
		var marketId *string = this.SafeString(message, "symbol")
		var symbol *string = this.SafeSymbol(marketId)
		var hashes map[string]any = map[string]any{
			"order-book":    "orderbook:" + *symbol,
			"public-trades": "trades:" + *symbol,
			"my-orders":     "orders",
			"my-trades":     "myTrades",
			"my-balance":    "balance",
		}
		var messageHash *string = this.SafeString(hashes, name)
		if messageHash != nil {
			client.(ccxt.ClientInterface).Reject(exception, messageHash)
			if (name != nil && *name == "my-orders") || (name != nil && *name == "my-trades") {
				// the private channels are account-wide, a symbol-scoped watchOrders / watchMyTrades waits on orders:SYMBOL / myTrades:SYMBOL
				var scopedPrefix string = *messageHash + ":"
				var pendingHashes []string = client.(ccxt.ClientInterface).FutureKeys()
				for i := 0; i < len(pendingHashes); i++ {
					var pendingHash string = pendingHashes[i]
					if strings.HasPrefix(pendingHash, scopedPrefix) {
						client.(ccxt.ClientInterface).Reject(exception, pendingHash)
					}
				}
			}
			if (name != nil) && (client.(ccxt.ClientInterface).SubscriptionHas(name)) {
				client.(ccxt.ClientInterface).SubscriptionDel(name)
			}
			if client.(ccxt.ClientInterface).SubscriptionHas(messageHash) {
				client.(ccxt.ClientInterface).SubscriptionDel(messageHash)
			}
		}
	}
}
func (this *Bit2me) HandleMessage(client any, message map[string]any) {
	var event *string = this.SafeString(message, "event")
	if event != nil && *event == "authenticate" {
		this.HandleAuthenticate(client, message)
		return
	}
	var error any = this.SafeValue(message, "error")
	if error != nil {
		this.HandleErrorMessage(client, message)
		return
	}
	var methods map[string]any = map[string]any{
		"order-book":          this.HandleOrderBook,
		"public-trades":       this.HandleTrades,
		"my-orders":           this.HandleOrder,
		"my-trades":           this.HandleMyTrade,
		"my-balance":          this.HandleBalance,
		"added-order":         this.HandleCreateOrder,
		"canceled-order":      this.HandleCancelOrder,
		"canceled-orders":     this.HandleCancelOrders,
		"canceled-all-orders": this.HandleCancelAllOrders,
		"subscribe":           this.HandleSubscriptionStatus,
		"unsubscribe":         this.HandleSubscriptionStatus,
	}
	var method any = this.SafeValue(methods, event)
	if method != nil {
		ccxt.CallDynamically(method, client, message)
	}
}

func NewBit2me(userConfig map[string]any) *Bit2me {
	p := newBit2me()
	p.Init(userConfig)
	return p
}

func (this *Bit2me) Init(userConfig map[string]any) {
	this.base.Init(this.DeepExtend(this.Describe(), userConfig))
	this.Itf = this
	this.Exchange.DerivedExchange = this
}

